    <script>
    document.addEventListener('DOMContentLoaded',()=>{const total=document.getElementById('order-estimated-total'),slot=document.getElementById('selected_slot_id'),submit=document.getElementById('submitBtn'),status=document.getElementById('barber-order-status'),inputs=document.querySelectorAll('[data-addon-input]'),image=document.getElementById('service-gallery-main'),format=new Intl.NumberFormat('id-ID'),slots={{ $service->time_slots_enabled ? 'true':'false' }};const updateTotal=()=>{const extra=[...inputs].filter(i=>i.checked).reduce((sum,i)=>sum+Number(i.dataset.addonPrice||0),0);total.textContent=`Rp${format.format(Number(total.dataset.basePrice)+extra)}`};window.updateSubmitButton=(id)=>{if(!slots)return;submit.disabled=!id;submit.querySelector('span').textContent=id?'Lanjutkan pesanan':'Pilih waktu dulu';if(id)status.textContent='Waktu booking dipilih. Kamu dapat melanjutkan pesanan.'};inputs.forEach(i=>i.addEventListener('change',()=>{updateTotal();status.textContent=`${i.checked?'Ditambahkan':'Dihapus'}: ${i.closest('label').querySelector('strong').textContent}. Total pesanan diperbarui.`}));document.querySelectorAll('[data-gallery-src]').forEach(b=>b.addEventListener('click',()=>{if(image)image.src=b.dataset.gallerySrc;document.querySelectorAll('[data-gallery-src]').forEach(x=>x.classList.toggle('is-active',x===b))}));updateTotal();window.updateSubmitButton(slot?.value)});
